  void OnEnable(){if(game!=null){tracking=false;dragX=0;opened=Time.unscaledTime;Select(0);}}
  public void Select(int value){direction=value>=Step?1:-1;Step=Mathf.Clamp(value,0,2);tracking=false;dragX=0;started=Time.unscaledTime;if(title==null)return;title.text=titles[Step];caption.text=captions[Step];pager.text=(Step+1)+" / 3";for(int i=0;i<3;i++){dots[i].color=i==Step?Art.Hex("A57A30"):Art.Hex("DDCDA7");dots[i].rectTransform.localScale=new Vector3(i==Step?2.4f:1,1,1);}Render();}
  public void RestoreProgress(int step,float elapsed){Select(step);started=Time.unscaledTime-Mathf.Clamp(elapsed,0,Duration-.001f);opened=Time.unscaledTime-.25f;}
  void Update(){if(card==null)return;if(!tracking&&focusLostAt<0&&DemoTime>=Duration){Advance();if(!isActiveAndEnabled)return;}cardFade.alpha=1;Render();}
