  void PoseBall(float x,float y,float alpha,float rotation){At(ball,x,y,alpha,1,rotation);At(ballShadow,x,y+20,alpha*.4f);}
  void Trail(float roll,bool show,float from,float to){for(int i=0;i<trails.Length;i++){trails[i].gameObject.SetActive(show);float p=Mathf.Max(0,roll-(i+1)*.055f);At(trails[i],240,Mathf.Lerp(from,to,p),(1-i*.22f)*.12f,1-i*.1f,-p*150);}}
  static float Smooth(float a,float b,float t){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,t));}
  static void At(Image image,float x,float y,float alpha,float scale=1,float rotation=0){var r=image.rectTransform;r.pivot=Vector2.one*.5f;r.anchoredPosition=new Vector2(x,-y);r.localScale=Vector3.one*scale;r.localRotation=Quaternion.Euler(0,0,rotation);var c=image.color;c.a=alpha;image.color=c;var group=image.GetComponent<CanvasGroup>();if(group!=null)group.alpha=alpha;}
  RectTransform R(string name,Transform parent,float x,float y,float w,float h){var o=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));o.layer=5;var r=o.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
  Image Surface(string name,Transform parent,float x,float y,float w,float h,string color){var img=R(name,parent,x,y,w,h).gameObject.AddComponent<CrispShape>();img.Radius=8;img.raycastTarget=false;img.color=Art.Hex(color);return img;}
  Image Icon(string name,Transform parent,Sprite sprite,float w,float h){var img=Surface(name,parent,0,0,w,h,"FFFFFF");img.sprite=sprite;img.type=Image.Type.Simple;img.preserveAspect=true;return img;}
  Text TextAt(string name,Transform parent,float x,float y,float w,float h,string text,int size,string color){var v=R(name,parent,x,y,w,h).gameObject.AddComponent<CrispText>();v.font=font;v.fontSize=Mathf.Max(Mathf.Max(size,19),Mathf.CeilToInt(12/Mathf.Max(.1f,Mathf.Min(hud.AppRect.width/600,(CrispUI.Height-24)/656f))));v.fontStyle=FontStyle.Bold;v.text=text;v.color=Art.Hex(color);v.alignment=TextAnchor.MiddleCenter;v.raycastTarget=false;v.horizontalOverflow=HorizontalWrapMode.Wrap;v.verticalOverflow=VerticalWrapMode.Overflow;return v;}
  void Advance(){if(Step<2)Select(Step+1);else Select(Step);}
  void OnDisable(){tracking=false;dragX=0;focusLostAt=-1;}
  void OnApplicationFocus(bool focused){if(!isActiveAndEnabled)return;if(!focused){if(tracking){started+=Time.unscaledTime-touchAt;tracking=false;dragX=0;}focusLostAt=Time.unscaledTime;}else if(focusLostAt>=0){started+=Time.unscaledTime-focusLostAt;focusLostAt=-1;}}
  public void OnPointerDown(PointerEventData e){if(tracking||e.button!=PointerEventData.InputButton.Left)return;tracking=true;touchId=e.pointerId;touchStart=e.position;touchAt=Time.unscaledTime;dragX=0;}
  public void OnBeginDrag(PointerEventData e){OnDrag(e);}
  public void OnDrag(PointerEventData e){if(tracking&&e.pointerId==touchId)dragX=e.position.x-touchStart.x;}
  public void OnPointerUp(PointerEventData e){FinishSwipe(e);}
  public void OnEndDrag(PointerEventData e){FinishSwipe(e);}
  void FinishSwipe(PointerEventData e){if(!tracking||touchId!=e.pointerId)return;started+=Time.unscaledTime-touchAt;tracking=false;var delta=e.position-touchStart;dragX=0;float threshold=Mathf.Clamp(hud.AppRect.width*.08f,32,64);if(Mathf.Abs(delta.x)>=threshold&&Mathf.Abs(delta.x)>Mathf.Abs(delta.y)*1.25f){if(delta.x<0)Advance();else if(Step>0)Select(Step-1);}}
  static Sprite Rounded(){if(round!=null)return round;round=Sprite.Create(Texture2D.whiteTexture,new Rect(0,0,1,1),Vector2.one*.5f,100);return round;}
